D["easy"] = [
 {"title":"Background: From Arnold and Leavis to Cultural Studies","story":"Pehle Matthew Arnold bolte the ki culture matlab 'the best that has been thought and said' - yaani sirf bade log ki oonchi cheezein. F. R. Leavis bhi kehte the ki ek chhoti 'minority' hi asli culture bachati hai, aur mass culture kharab hai. Socho mummy kehti hai sirf classical music achha hai, filmi gaane bekaar. Phir Cultural Studies wale aaye aur bole: nahi bhai, gali ka gaana, TV, cricket - sab culture hai. Isse 'high culture vs popular culture' ki deewar tooti.","trick":"A-L-W: Arnold (1869 Culture and Anarchy) - Leavis (1930 Mass Civilization and Minority Culture) - Williams ('culture is ordinary'). Oonchi seedhi se zameen tak!"},
 {"title":"Birmingham CCCS (Centre for Contemporary Cultural Studies)","story":"1964 mein Birmingham University mein ek chhota sa centre bana - CCCS. Iske pehle director Richard Hoggart the, phir Stuart Hall aaye. Yahan log TV, punk, school ke ladke, akhbaar sab ko padhte the jaise koi kitab padhta hai. Socho ek kamra jahan sab mohalle ki baatein seriously discuss hoti hain. 2002 mein ye department band ho gaya.","trick":"64 mein Birmingham ka 'Chai Club' khula: Hoggart ne chai banayi, Hall ne serve ki, 2002 mein dukaan band."},
 {"title":"Richard Hoggart and E. P. Thompson","story":"Hoggart ne 1957 mein 'The Uses of Literacy' likhi - working class ki zindagi aur unpar sasti magazines ka asar. E. P. Thompson ne 1963 mein 'The Making of the English Working Class' likhi. Thompson kehte the class koi cheez nahi, ek 'happening' hai jo log khud banate hain. Jaise gaon ke log milke khud apni panchayat banate hain, koi upar se nahi deta. Thompson ne 'history from below' ko famous kiya.","trick":"Hoggart = 57 = 'Literacy' (L for Lettering). Thompson = 63 = 'Making' (M after L). Class is 'made', not 'found'."},
 {"title":"Raymond Williams and Cultural Materialism","story":"Raymond Williams ek Welsh railway signalman ke bete the. Unhone kaha 'Culture is ordinary' - culture sabka hai, sirf amiron ka nahi. Unki books: Culture and Society (1958), The Long Revolution (1961), Keywords (1976), Marxism and Literature (1977). 'Structure of feeling' matlab kisi zamane ka common mood, jaise 90s ke bachchon ka Doordarshan wala feeling. Unhone dominant, residual, emergent culture ki baat ki.","trick":"Williams ki 'DRE-ss': Dominant, Residual, Emergent. Aur 'Keywords' 76 mein - 'Key 76'."},
 {"title":"Stuart Hall","story":"Stuart Hall Jamaica se England aaye aur CCCS ke acting director (1968) aur phir director (1972-1979) bane. Unka famous essay 'Encoding/Decoding' (1973) kehta hai ki TV message bhejta hai, par dekhne wala apne tareeke se samajhta hai. Jaise papa news dekh ke khush, chacha naraz - same news, alag reading. Teen tarah ki reading: dominant (maan liya), negotiated (aadha maana), oppositional (bilkul ulta). 'Policing the Crisis' (1978) mein mugging ke moral panic ko samjhaya.","trick":"Hall ki 'DNO' reading: Dominant, Negotiated, Oppositional - 'Do Na O'!"},
 {"title":"Youth Subcultures, Style and Moral Panics","story":"Punk, Mods, Rockers, Teddy Boys - ye youth groups apne kapde, baal aur music se 'style' dikhate the. Dick Hebdige ne 'Subculture: The Meaning of Style' (1979) mein kaha ye style ek tarah ka virodh hai, 'bricolage' se bana. Stanley Cohen ne 'Folk Devils and Moral Panics' (1972) mein dikhaya ki media chhoti baat ko bada darr bana deta hai. Jaise news channel bole 'PUBG se bachche bigad rahe hain!' - wahi moral panic.","trick":"Cohen 72 ke 'Devils', Hebdige 79 ka 'Style'. 'Resistance Through Rituals' 1975 - R-R ke beech mein."},
 {"title":"Frankfurt School and the Culture Industry","story":"Germany ke Frankfurt mein kuch Marxist thinker the - Adorno, Horkheimer, Marcuse. Adorno-Horkheimer ne 'Dialectic of Enlightenment' (1944/1947) mein 'Culture Industry' ki baat ki. Matlab filmein, gaane factory jaise ek jaise maal ki tarah bante hain aur logon ko chup karate hain. Jaise har TV serial mein same saas-bahu drama. Marcuse ne 'One-Dimensional Man' (1964) likhi.","trick":"Frankfurt ke 'AHM' chacha: Adorno, Horkheimer, Marcuse - sab bole 'Culture Industry = Factory'."},
 {"title":"Walter Benjamin","story":"Walter Benjamin ne 1936 mein essay likha 'The Work of Art in the Age of Mechanical Reproduction'. Unhone kaha asli painting mein ek 'aura' hoti hai - uski unique jagah aur samay. Jab photo copy, poster, film banti hai to aura khatam ho jaati hai. Jaise Taj Mahal khud dekhna aur uska fridge magnet - feel alag. Par Benjamin ko isme democracy bhi dikhi, kyunki sab tak art pahunchi. Unhone 'flâneur' aur 'Arcades Project' bhi diya.","trick":"Benjamin = 'Aura Uncle' 1936: copy machine aayi, aura gayi."},
 {"title":"Antonio Gramsci and Hegemony","story":"Gramsci Italy ke Marxist the jinhe Mussolini ne jail mein daala. Jail mein unhone 'Prison Notebooks' likhi. Hegemony matlab ruling class danda nahi, logon ki 'consent' (sehmati) se raaj karti hai. Jaise ad dekh ke hum khud maan lete hain ki gora rang achha - kisi ne zabardasti nahi ki. Unhone 'organic intellectual' aur 'subaltern' word bhi diya.","trick":"Gramsci = G for 'Gentle rule' = Hegemony by consent, not by danda."},
 {"title":"Louis Althusser and Ideological State Apparatuses","story":"Althusser French Marxist the. 1970 ke essay 'Ideology and Ideological State Apparatuses' mein do tarah ki machine batayi. RSA - police, army, court, jo force se chalate hain. ISA - school, family, church, media, jo ideology se chalate hain. 'Interpellation' matlab jab policewala bole 'Oye, tum!' aur tum mud jao - tum subject ban gaye.","trick":"RSA = Rifle wali (force), ISA = Idea wali (school, family). 'Hey you!' = interpellation."},
 {"title":"Roland Barthes: Mythologies and Semiology","story":"Barthes French thinker the. 'Mythologies' (1957) mein wrestling, soap powder, wine jaisi roz ki cheezon ko padha. Unhone kaha myth ek 'second-order' meaning hai - pehle sign, phir uspe naya chhupa meaning. Famous example: Paris Match cover par French uniform mein kala sipahi salute karta hai, matlab 'French empire sabke liye achha'. Jaise cricket jersey sirf kapda nahi, deshbhakti ka sign. 1967 mein 'The Death of the Author' likha.","trick":"Barthes ka 'saluting soldier' = myth. Mythologies 57 - Hoggart ke saath same saal!"},
 {"title":"Baudrillard, Simulation and Postmodern Media Theory","story":"Jean Baudrillard ne 'Simulacra and Simulation' (1981) likhi. Unhone kaha aaj copy itni zyada hai ki asli cheez gayab ho gayi - isse 'hyperreality' kehte hain. Disneyland unka famous example hai. Jaise Instagram filter wala chehra asli chehre se zyada 'real' lagne lage. Unhone provocatively kaha 'The Gulf War Did Not Take Place' (1991).","trick":"Baudrillard = 'Bau-Disney-lard': Disneyland + simulacra + hyperreal."},
 {"title":"Pierre Bourdieu: Taste, Capital and Field","story":"Bourdieu French sociologist the. 'Distinction' (1979) mein dikhaya ki taste (pasand) class se aata hai. Unhone capital ke prakar bataye: economic, cultural, social, symbolic. 'Habitus' matlab ghar aur parvarish se bani aadatein, jaise khana chammach se ya haath se. 'Field' matlab ek khel ka maidan jahan log capital ke liye ladte hain.","trick":"Bourdieu ke 'HCF': Habitus, Capital, Field. Taste = class ka chashma."},
 {"title":"John Fiske and Popular Culture Studies","story":"John Fiske ne 'Television Culture' (1987) aur 'Understanding Popular Culture' (1989) likhi. Unhone kaha audience bewakoof nahi, active hai - apna meaning khud banata hai. Jaise ek ad ko hum mazaak bana ke meme bana dete hain. Unhone 'semiotic democracy' aur 'polysemy' ki baat ki. Kuch critics ne inhe 'cultural populism' ka example bola.","trick":"Fiske = 'Fun-ske': popular culture fun hai, audience active."},
 {"title":"Subaltern Studies","story":"Subaltern matlab neeche dabaye gaye log - kisan, dalit, adivasi, auratein. Ranajit Guha ne 1982 mein Subaltern Studies group shuru kiya, jo itihas ko neeche se dekhna chahta tha. Gayatri Spivak ne puchha 'Can the Subaltern Speak?' aur kaha ki dabe hue log ki awaaz koi aur bol deta hai. Jaise gaon ki kahani hamesha zamindar sunata hai, kisan nahi. Word Gramsci se aaya.","trick":"Guha 82 ne group shuru kiya, Spivak ne sawaal puchha: 'Bol sakta hai kya?'"},
 {"title":"Gender, Sexuality and Queer Theory in Cultural Studies","story":"Judith Butler ne 'Gender Trouble' (1990) mein kaha gender ek 'performance' hai - hum roz dohraake usse banate hain. Jaise ladkon ko bolna 'ladke rote nahi' - ye baar baar dohraake gender banta hai. Eve Sedgwick ne 'Epistemology of the Closet' (1990) likhi. Laura Mulvey ne 1975 mein 'male gaze' diya - film mein camera aadmi ki nazar se dekhta hai. Teresa de Lauretis ne 'queer theory' term popular kiya (1990/91).","trick":"1990 = Butler + Sedgwick ka 'Queer saal'. Mulvey 75 = 'Male gaze'."},
 {"title":"Ecocriticism","story":"Ecocriticism matlab literature ko prakriti aur paryavaran ke nazariye se padhna. William Rueckert ne 1978 mein 'ecocriticism' word banaya. Cheryll Glotfelty ne kaha ye 'literature aur physical environment ka rishta' hai (The Ecocriticism Reader, 1996). Jaise Ganga par kavita ko pollution ke angle se padhna. Lawrence Buell, Greg Garrard, Jonathan Bate bhi naam hain; India mein Amitav Ghosh ki 'The Great Derangement' (2016).","trick":"Rueckert 78 ne naam diya, Glotfelty 96 ne Reader diya - 'R-G' = Ret aur Ghaas."},
 {"title":"Digital Culture, New Media and Indian Cultural Studies","story":"Marshall McLuhan ne kaha 'The medium is the message' (Understanding Media, 1964) aur 'global village' ki baat ki. Henry Jenkins ne 'Convergence Culture' (2006) aur fans ki participatory culture samjhayi. Donna Haraway ne 'A Cyborg Manifesto' (1985) likha. India mein Ashis Nandy, Partha Chatterjee jaise log culture ko apne nazariye se padhte hain. Jaise WhatsApp family group - naya digital culture!","trick":"McLuhan 64 'Medium = Message', Jenkins 2006 'Convergence', Haraway 85 'Cyborg'."},
]
